import type { CreateBookingInput, ListBookingsInput, UpdateBookingInput } from './schema.js';

function assertValidRange(startsAt: Date, endsAt: Date): void {
  if (!isBefore(startsAt, endsAt)) {
    throw validationFailed('startsAt must be before endsAt', {
      startsAt: startsAt.toISOString(),
      endsAt: endsAt.toISOString(),
    });
  }
}

export async function createBooking(input: CreateBookingInput): Promise<Booking> {
  const startsAt = parseInstant(input.startsAt);
  const endsAt = parseInstant(input.endsAt);
  assertValidRange(startsAt, endsAt);

  if (!(await findRoomById(input.roomId))) {
    throw notFound('Room');
  }
  if (!(await findUserById(input.userId))) {
    throw notFound('User');
  }

  const conflict = await repository.findOverlap(input.roomId, startsAt, endsAt);
  if (conflict) {
    throw bookingConflict(conflict.id);
  }

  return repository.create({
    roomId: input.roomId,
    userId: input.userId,
    title: input.title,
    startsAt,
    endsAt,
  });
}

export async function getBooking(id: string): Promise<Booking> {
